import unittest
from src.b import total

class AppTest(unittest.TestCase):
    def test_values(self):
        self.assertEqual(total([1, 2, 3]), 12)
    def test_empty(self):
        self.assertEqual(total([]), 0)
    def test_negative(self):
        self.assertEqual(total([-3, 2]), -2)
